	UpdateOS = function()
		local dateStr = os.date("*t")
		local number = dateStr.hour % 24
		local condition = number < 12

		if condition then
			condition = "AM"
		end

		local text = string.format("%02i:%02i:%02i %s", (number - 1) % 12 + 1, dateStr.min, dateStr.sec, condition or "PM")
