require(game.ReplicatedStorage.EventConfig.MagnetEvent26)
data.Main:AddSection("Update 30 / Magnet Token")

do
	local magnetEventStatusParagraph = data.Main:AddParagraph("Magnet Event Status", "Loading...")
	local statusParagraph = data.Main:AddParagraph("Status", "Status : Idle")

	SetMagnetStatus = function(status)
		if statusParagraph and statusParagraph.SetDesc then
			local value2, value3

			pcall(function()
				statusParagraph:SetDesc("Status : " .. status)
			end)
		end
	end

	task.spawn(function()
		if task.wait(1) then
			repeat
				pcall(function()
					local now = os.time()
					local dateStr = os.date("*t", now)
					local min = dateStr.min
					local sec = dateStr.sec
					local condition = min >= 0

					if condition then
						condition = min < 10
					end

					local value2, value3, value4 = pairs(workspace.Enemies:GetChildren())
					local iter_z_1 = (function(iteratorFn, state, control) local co = coroutine.wrap(function() coroutine.yield(); for key, item, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth in iteratorFn, state, control do coroutine.yield(true, key, item, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth) end end); co(); return co end)(value3, value4)
					local exitTo = nil
					local value5

					while true do
						local value6 = table.pack(iter_z_1())

						if not value6[1] then
							exitTo = 1
							break
						else
							value5 = value6[3]
							if not value5:IsA("Model") then
								continue
							end
							break
						end
					end

					local text, text2, number, text3, number2

					if exitTo == 1 then
						text = "🔴"

						if condition then
							text2 = "🟢"
							number = (10 - min) * 60 - sec

							if number < 0 then
								number = 0
							end

							text3 = string.format("%s ACTIVE - Time Left: %02d:%02d", text2, math.floor(number / 60), number % 60)
						else
							number2 = (60 - min) * 60 - sec

							if number2 <= 0 then
								number2 = 0
							end

							text3 = string.format("%s INACTIVE - Next Event: %02d:%02d", text, math.floor(number2 / 60), number2 % 60)
						end
					else
						local attribute = value5:GetAttribute("MagnetEnemy")
						local exitTo3 = nil

						while attribute ~= true do
							if not string.find(string.lower(value5.Name), "magnetized") then
								local exitTo2 = nil

								while true do
									local value6 = table.pack(iter_z_1())

									if not value6[1] then
										exitTo2 = 1
										break
									else
										value5 = value6[3]
										if not value5:IsA("Model") then
											continue
										end
										break
									end
								end

								if exitTo2 == 1 then
									exitTo3 = 1
									break
								else
									attribute = value5:GetAttribute("MagnetEnemy")
									continue
								end
							end

							break
						end

						if exitTo3 == 1 then
							text = "🔴"

							if condition then
								text2 = "🟢"
								number = (10 - min) * 60 - sec

								if number < 0 then
									number = 0
								end

								text3 = string.format("%s ACTIVE - Time Left: %02d:%02d", text2, math.floor(number / 60), number % 60)
							else
								number2 = (60 - min) * 60 - sec

								if number2 <= 0 then
									number2 = 0
								end

								text3 = string.format("%s INACTIVE - Next Event: %02d:%02d", text, math.floor(number2 / 60), number2 % 60)
							end
						else
							local text4 = "🟢"
							local number3 = (10 - min) * 60 - sec

							if number3 < 0 then
								number3 = 0
							end

							text3 = string.format("%s ACTIVE - Time Left: %02d:%02d (✅ Enemies Found)", text4, math.floor(number3 / 60), number3 % 60)
						end
					end

					magnetEventStatusParagraph:SetDesc(text3)
				end)
			until not task.wait(1)
		end
	end)
end

