data.Race:AddSection("Mystic Island / Full Moon")

do
	local fullMoonStatusParagraph = data.Race:AddParagraph("FullMoon Status", "")
	local mirageIslandStatusParagraph = data.Race:AddParagraph("Mirage Island Status", "")

	spawn(function()
		if wait(0.2) then
			local exitTo2, map

			if workspace.Map:FindFirstChild("MysticIsland") then
				local exitTo = nil

				while true do
					mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

					if wait(0.2) then
						if not workspace.Map:FindFirstChild("MysticIsland") then
							exitTo = 1
							break
						end
					else
						break
					end
				end

				if exitTo == 1 then
					while true do
						local locations = workspace._WorldOrigin.Locations

						if locations:FindFirstChild("Mirage Island") then
							exitTo2 = nil

							while true do
								mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

								if wait(0.2) then
									map = workspace.Map

									if map:FindFirstChild("MysticIsland") then
										continue
									else
										exitTo2 = 1
										break
									end
								end

								break
							end

							if exitTo2 == 1 then
								continue
							end
							break
						else
							mirageIslandStatusParagraph:SetDesc("Mirage Island : False")

							if wait(0.2) then
								map = workspace.Map

								if map:FindFirstChild("MysticIsland") then
									exitTo2 = nil

									while true do
										mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

										if wait(0.2) then
											map = workspace.Map

											if map:FindFirstChild("MysticIsland") then
												continue
											else
												exitTo2 = 1
												break
											end
										end

										break
									end

									if exitTo2 == 1 then
										continue
									end
								else
									continue
								end
							end

							break
						end
					end
				end
			else
				local exitTo3 = nil

				while true do
					if workspace._WorldOrigin.Locations:FindFirstChild("Mirage Island") then
						exitTo3 = 1
						break
					else
						mirageIslandStatusParagraph:SetDesc("Mirage Island : False")

						if wait(0.2) then
							if workspace.Map:FindFirstChild("MysticIsland") then
								exitTo3 = 1
								break
							else
								continue
							end
						end

						break
					end
				end

				if exitTo3 == 1 then
					local exitTo4 = nil

					while true do
						mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

						if wait(0.2) then
							map = workspace.Map

							if map:FindFirstChild("MysticIsland") then
								continue
							else
								exitTo4 = 1
								break
							end
						end

						break
					end

					if exitTo4 == 1 then
						while true do
							if workspace._WorldOrigin.Locations:FindFirstChild("Mirage Island") then
								exitTo2 = nil

								while true do
									mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

									if wait(0.2) then
										map = workspace.Map

										if map:FindFirstChild("MysticIsland") then
											continue
										else
											exitTo2 = 1
											break
										end
									end

									break
								end

								if exitTo2 == 1 then
									continue
								end
								break
							else
								mirageIslandStatusParagraph:SetDesc("Mirage Island : False")

								if wait(0.2) then
									map = workspace.Map

									if map:FindFirstChild("MysticIsland") then
										exitTo2 = nil

										while true do
											mirageIslandStatusParagraph:SetDesc("Mirage Island : True")

											if wait(0.2) then
												map = workspace.Map

												if map:FindFirstChild("MysticIsland") then
													continue
												else
													exitTo2 = 1
													break
												end
											end

											break
										end

										if exitTo2 == 1 then
											continue
										end
									else
										continue
									end
								end

								break
							end
						end
					end
				end
			end
		end
	end)

	spawn(function()
		if wait(0.2) then
			repeat
				pcall(function()
					local value2 = Getmoon()

					if value2 ~= "http://www.roblox.com/asset/?id=9709135895" then
						if value2 ~= "http://www.roblox.com/asset/?id=9709139597" then
							if value2 ~= "http://www.roblox.com/asset/?id=9709143733" then
								if value2 ~= "http://www.roblox.com/asset/?id=9709149052" then
									if value2 ~= "http://www.roblox.com/asset/?id=9709149431" then
										if value2 ~= "http://www.roblox.com/asset/?id=9709149680" then
											if value2 ~= "http://www.roblox.com/asset/?id=9709150086" then
												if value2 == "http://www.roblox.com/asset/?id=9709150401" then
													fullMoonStatusParagraph:SetDesc("Moon : 7 / 8")
												end
											else
												fullMoonStatusParagraph:SetDesc("Moon : 6 / 8")
											end
										else
											fullMoonStatusParagraph:SetDesc("Moon : 5 / 8 [ Last Night ]")
										end
									else
										fullMoonStatusParagraph:SetDesc("Moon : 4 / 8 [ Full Moon ]")
									end
								else
									fullMoonStatusParagraph:SetDesc("Moon : 3 / 8 [ Next Night ]")
								end
							else
								fullMoonStatusParagraph:SetDesc("Moon : 2 / 8")
							end
						else
							fullMoonStatusParagraph:SetDesc("Moon : 1 / 8")
						end
					else
						fullMoonStatusParagraph:SetDesc("Moon : 0 / 8")
					end
				end)
			until not wait(0.2)
		end
	end)
end

