	Callback = function(teleport)
		_G.Teleport = teleport

		if teleport then
			local value2, value3, value4 = pairs(workspace._WorldOrigin.Locations:GetChildren())
			local iter_z_1 = (function(iteratorFn, state, control) local co = coroutine.wrap(function() coroutine.yield(); for key, item, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth in iteratorFn, state, control do coroutine.yield(true, key, item, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth) end end); co(); return co end)(value3, value4)
			local exitTo = nil
			local value5

			while true do
				local value6 = table.pack(iter_z_1())

				if not value6[1] then
					break
				else
					value5 = value6[3]
					if value5.Name == _G.Island then
						exitTo = 1
						break
					end
				end
			end

			if exitTo == 1 then
				wait()
				local value6 = _tp
				local cFrame = value5.CFrame
				local cFrameNew = CFrame.new
				local number = 0
				local exitTo2 = nil

				while true do
					value6(cFrame * cFrameNew(number, 30, 0))

					if _G.Teleport then
						exitTo2 = 1
						break
					else
						local exitTo3 = nil

						while true do
							local value7 = table.pack(iter_z_1())

							if not value7[1] then
								break
