								value5 = value7[3]
								if value5.Name == _G.Island then
									exitTo3 = 1
									break
								end
							end
						end

						if exitTo3 == 1 then
							wait()
							value6 = _tp
							cFrame = value5.CFrame
							cFrameNew = CFrame.new
							continue
						end

						break
					end
				end

				if exitTo2 == 1 then
					while true do
						if Root.CFrame ~= value5.CFrame then
							wait()
							_tp(value5.CFrame * CFrame.new(0, 30, 0))
							if _G.Teleport then
								continue
							end
						end

						local exitTo4 = nil

						while true do
							local value7 = table.pack(iter_z_1())

